    }

    .Days {
        display: grid;
        grid-template-columns: repeat(7, 1fr);
        flex-direction: row;
        flex-wrap: wrap;
        justify-content: start;
        align-items: start;
        gap: var(--space-xs);
    }
    .DayName {
        display: flex;
        text-box: trim-both cap alphabetic;
        justify-content: center;
