        text-box: trim-both cap alphabetic;
    }
    .Field input {
        font-family: var(--font-family-mono);
        font-weight: 500;
        font-size: 1.5em;
        border: none;
        padding: var(--space-md) var(--space-xs);
        line-height: 1.5;
